#!/usr/bin/env python3
"""Write sw/programs/crc.c: CRC-32 (IEEE 802.3) with a 256-entry lookup table in .rodata."""
from pathlib import Path


def crc_table():
    table = []
    for n in range(256):
        c = n
        for _ in range(8):
            c = (c >> 1) ^ 0xEDB88320 if c & 1 else c >> 1
        table.append(c)
    return table


def main():
    t = crc_table()
    rows = ",\n".join("    " + ", ".join(f"0x{v:08X}u" for v in t[i:i + 4]) for i in range(0, 256, 4))
    src = (
        '/* CRC-32 (IEEE 802.3) with a lookup table in .rodata.\n'
        '   Generated by scripts/gen_crc_c.py. The CRC-32 of "123456789" is the published\n'
        '   check value 0xCBF43926. */\n'
        'static const unsigned crc_table[256] = {\n' + rows + '\n};\n\n'
        'static const char message[] = "123456789";\n\n'
        'int main(void) {\n'
        '    volatile unsigned len = sizeof(message) - 1;\n'
        '    unsigned crc = 0xFFFFFFFFu;\n'
        '    for (unsigned i = 0; i < len; i++)\n'
        '        crc = crc_table[(crc ^ (unsigned char)message[i]) & 0xFFu] ^ (crc >> 8);\n'
        '    return (int)(crc ^ 0xFFFFFFFFu);\n'
        '}\n'
    )
    out = Path(__file__).resolve().parent.parent / "sw" / "programs" / "crc.c"
    out.write_text(src)
    print(f"wrote {out} (table entry 1 = {t[1]:#010x}, expected 0x77073096)")


main()
